CREATE TABLE projects (id TEXT PRIMARY KEY, name TEXT NOT NULL, path TEXT NOT NULL UNIQUE, preview_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE model_providers (id TEXT PRIMARY KEY, name TEXT NOT NULL, adapter TEXT NOT NULL DEFAULT 'openai-compatible' CHECK(adapter='openai-compatible'), base_url TEXT NOT NULL, credential_ref TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE model_configs (id TEXT PRIMARY KEY, provider_id TEXT NOT NULL REFERENCES model_providers(id), name TEXT NOT NULL, model_name TEXT NOT NULL, parameters_json TEXT NOT NULL DEFAULT '{}', context_budget_tokens INTEGER NOT NULL DEFAULT 8000 CHECK(context_budget_tokens>0), input_types_json TEXT NOT NULL DEFAULT '["text"]', enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE agents (id TEXT PRIMARY KEY, name TEXT NOT NULL, instructions TEXT NOT NULL DEFAULT '', model_config_id TEXT NOT NULL REFERENCES model_configs(id), allowed_tools_json TEXT NOT NULL DEFAULT '["*"]', revision INTEGER NOT NULL DEFAULT 1, enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE workflows (id TEXT PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('single','frontend-review')), revision INTEGER NOT NULL DEFAULT 1, max_revisions INTEGER NOT NULL DEFAULT 2 CHECK(max_revisions BETWEEN 0 AND 2), enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE workflow_steps (id TEXT PRIMARY KEY, workflow_id TEXT NOT NULL REFERENCES workflows(id) ON DELETE CASCADE, step_key TEXT NOT NULL, position INTEGER NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('code','capture','review','summary')), agent_id TEXT REFERENCES agents(id), UNIQUE(workflow_id,step_key), UNIQUE(workflow_id,position), CHECK((kind='capture' AND agent_id IS NULL) OR (kind!='capture' AND agent_id IS NOT NULL)));
CREATE TABLE sessions (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), workflow_id TEXT REFERENCES workflows(id), title TEXT NOT NULL, context_start_seq INTEGER NOT NULL DEFAULT 0, sandbox_mode TEXT NOT NULL DEFAULT 'workspace-write', approval_mode TEXT NOT NULL DEFAULT 'interactive', archived_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE runs (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, request_key TEXT NOT NULL, goal TEXT NOT NULL, mode TEXT NOT NULL DEFAULT 'run', status TEXT NOT NULL, config_snapshot_json TEXT NOT NULL, state_json TEXT NOT NULL DEFAULT '{}', error TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, ended_at TEXT, UNIQUE(session_id,request_key));
CREATE UNIQUE INDEX one_active_run ON runs(session_id) WHERE status IN ('queued','running','waiting');
CREATE TABLE agent_runs (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id) ON DELETE CASCADE, step_key TEXT NOT NULL, agent_id TEXT REFERENCES agents(id), iteration INTEGER NOT NULL, status TEXT NOT NULL, input_json TEXT NOT NULL, output TEXT NOT NULL DEFAULT '', error TEXT NOT NULL DEFAULT '', usage_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(run_id,step_key,iteration));
CREATE TABLE messages (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, run_id TEXT REFERENCES runs(id) ON DELETE CASCADE, agent_run_id TEXT REFERENCES agent_runs(id) ON DELETE CASCADE, seq INTEGER NOT NULL, role TEXT NOT NULL CHECK(role IN ('user','assistant','system','tool')), kind TEXT NOT NULL DEFAULT 'message', content_text TEXT NOT NULL, content_json TEXT NOT NULL DEFAULT '[]', status TEXT NOT NULL DEFAULT 'completed', visibility TEXT NOT NULL DEFAULT 'public' CHECK(visibility IN ('public','internal')), created_at TEXT NOT NULL, UNIQUE(session_id,seq));
CREATE TABLE tasks (id TEXT PRIMARY KEY, agent_run_id TEXT NOT NULL REFERENCES agent_runs(id) ON DELETE CASCADE, task_key TEXT NOT NULL, description TEXT NOT NULL, tool TEXT NOT NULL, args_json TEXT NOT NULL, effort TEXT NOT NULL, status TEXT NOT NULL, output TEXT NOT NULL DEFAULT '', error TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(agent_run_id,task_key));
CREATE TABLE artifacts (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id) ON DELETE CASCADE, agent_run_id TEXT REFERENCES agent_runs(id) ON DELETE CASCADE, kind TEXT NOT NULL, path TEXT NOT NULL UNIQUE, sha256 TEXT NOT NULL, size INTEGER NOT NULL, media_type TEXT NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE reviews (id TEXT PRIMARY KEY, agent_run_id TEXT NOT NULL UNIQUE REFERENCES agent_runs(id) ON DELETE CASCADE, code_agent_run_id TEXT NOT NULL REFERENCES agent_runs(id) ON DELETE CASCADE, iteration INTEGER NOT NULL, verdict TEXT NOT NULL CHECK(verdict IN ('passed','changes_requested','unable_to_review')), summary TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE review_artifacts (review_id TEXT NOT NULL REFERENCES reviews(id) ON DELETE CASCADE, artifact_id TEXT NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE, PRIMARY KEY(review_id,artifact_id));
CREATE TABLE review_findings (id TEXT PRIMARY KEY, review_id TEXT NOT NULL REFERENCES reviews(id) ON DELETE CASCADE, severity TEXT NOT NULL CHECK(severity IN ('blocking','suggestion')), description TEXT NOT NULL, artifact_id TEXT NOT NULL REFERENCES artifacts(id), location TEXT NOT NULL, suggestion TEXT NOT NULL, bbox_json TEXT, previous_finding_id TEXT REFERENCES review_findings(id) ON DELETE SET NULL);
CREATE TABLE interactions (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id) ON DELETE CASCADE, agent_run_id TEXT REFERENCES agent_runs(id) ON DELETE CASCADE, interrupt_id TEXT NOT NULL, kind TEXT NOT NULL, request_json TEXT NOT NULL, response_json TEXT, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(run_id,interrupt_id));
CREATE TABLE run_events (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES runs(id) ON DELETE CASCADE, seq INTEGER NOT NULL, type TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(run_id,seq));
CREATE TABLE settings (key TEXT PRIMARY KEY, value_json TEXT NOT NULL);
CREATE TABLE legacy_imports (source_key TEXT PRIMARY KEY, imported_at TEXT NOT NULL);
CREATE INDEX sessions_updated ON sessions(updated_at DESC);
CREATE INDEX runs_session ON runs(session_id,created_at);
CREATE INDEX runs_status ON runs(status);
CREATE INDEX agent_runs_run ON agent_runs(run_id,created_at);
CREATE INDEX artifacts_run ON artifacts(run_id);
CREATE INDEX interactions_run ON interactions(run_id,status);
